CREATE TABLE IF NOT EXISTS financial_forecasts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),scope_id UUID NOT NULL,forecast_type TEXT NOT NULL CHECK(forecast_type IN('FUNDING_DELAY','RELEASE_DELAY','PAYMENT_FAILURE','LEAKAGE','RECONCILIATION_EXCEPTION')),model_id TEXT NOT NULL,model_version TEXT NOT NULL,predicted_value NUMERIC NOT NULL,confidence NUMERIC NOT NULL CHECK(confidence BETWEEN 0 AND 1),rationale TEXT NOT NULL,review_status TEXT NOT NULL CHECK(review_status IN('NOT_REVIEWED','ACCEPTED','REJECTED')),generated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS performance_scorecards(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),party_id UUID NOT NULL,party_role TEXT NOT NULL CHECK(party_role IN('VENDOR','CUSTOMER')),period_start DATE NOT NULL,period_end DATE NOT NULL,metrics JSONB NOT NULL,overall_score NUMERIC NOT NULL CHECK(overall_score BETWEEN 0 AND 100),computed_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(period_end>period_start));
CREATE TABLE IF NOT EXISTS portfolio_snapshots(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),scope_id TEXT NOT NULL,at_risk_count INTEGER NOT NULL CHECK(at_risk_count>=0),blocked_count INTEGER NOT NULL CHECK(blocked_count>=0),unpaid_amount_minor BIGINT NOT NULL CHECK(unpaid_amount_minor>=0),disputed_count INTEGER NOT NULL CHECK(disputed_count>=0),retained_amount_minor BIGINT NOT NULL CHECK(retained_amount_minor>=0),concentration_top_party_percent NUMERIC NOT NULL CHECK(concentration_top_party_percent BETWEEN 0 AND 100),currency TEXT NOT NULL,computed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS renewal_assessments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL,renewal_readiness_score NUMERIC NOT NULL CHECK(renewal_readiness_score BETWEEN 0 AND 100),performance_history_summary TEXT NOT NULL,recommended_action TEXT NOT NULL CHECK(recommended_action IN('RENEW','RENEGOTIATE','DO_NOT_RENEW','REVIEW_REQUIRED')),rationale TEXT NOT NULL,assessed_by UUID NOT NULL,assessed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS model_registrations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),model_id TEXT NOT NULL,model_version TEXT NOT NULL,purpose TEXT NOT NULL,governed_by TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('ACTIVE','DEPRECATED')),registered_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(workspace_id,model_id,model_version));
CREATE TABLE IF NOT EXISTS evaluation_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),model_registration_id UUID NOT NULL REFERENCES model_registrations(id),metric TEXT NOT NULL,score NUMERIC NOT NULL,threshold NUMERIC NOT NULL,passed BOOLEAN NOT NULL,evaluated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS drift_alerts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),model_registration_id UUID NOT NULL REFERENCES model_registrations(id),description TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN('LOW','MEDIUM','HIGH')),status TEXT NOT NULL CHECK(status IN('OPEN','ACKNOWLEDGED','RESOLVED')),raised_at TIMESTAMPTZ NOT NULL DEFAULT now(),resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS model_feedback(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),model_registration_id UUID NOT NULL REFERENCES model_registrations(id),output_reference TEXT NOT NULL,rating TEXT NOT NULL CHECK(rating IN('POSITIVE','NEGATIVE')),comment TEXT NOT NULL,submitted_by UUID NOT NULL,submitted_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS recommendations(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),scope_id UUID NOT NULL,model_registration_id UUID NOT NULL REFERENCES model_registrations(id),recommendation TEXT NOT NULL,confidence NUMERIC NOT NULL CHECK(confidence BETWEEN 0 AND 1),status TEXT NOT NULL CHECK(status IN('PENDING','ACCEPTED','DISMISSED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),decided_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS financial_forecasts_scope_type_idx ON financial_forecasts(workspace_id,scope_id,forecast_type);CREATE INDEX IF NOT EXISTS performance_scorecards_party_idx ON performance_scorecards(workspace_id,party_id,party_role);CREATE INDEX IF NOT EXISTS portfolio_snapshots_scope_idx ON portfolio_snapshots(workspace_id,scope_id);CREATE INDEX IF NOT EXISTS renewal_assessments_contract_idx ON renewal_assessments(workspace_id,contract_id);CREATE INDEX IF NOT EXISTS evaluation_records_model_idx ON evaluation_records(workspace_id,model_registration_id);CREATE INDEX IF NOT EXISTS drift_alerts_model_status_idx ON drift_alerts(workspace_id,model_registration_id,status);CREATE INDEX IF NOT EXISTS recommendations_scope_status_idx ON recommendations(workspace_id,scope_id,status);
ALTER TABLE financial_forecasts ENABLE ROW LEVEL SECURITY;ALTER TABLE performance_scorecards ENABLE ROW LEVEL SECURITY;ALTER TABLE portfolio_snapshots ENABLE ROW LEVEL SECURITY;ALTER TABLE renewal_assessments ENABLE ROW LEVEL SECURITY;ALTER TABLE model_registrations ENABLE ROW LEVEL SECURITY;ALTER TABLE evaluation_records ENABLE ROW LEVEL SECURITY;ALTER TABLE drift_alerts ENABLE ROW LEVEL SECURITY;ALTER TABLE model_feedback ENABLE ROW LEVEL SECURITY;ALTER TABLE recommendations ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['financial_forecasts','performance_scorecards','portfolio_snapshots','renewal_assessments','model_registrations','evaluation_records','drift_alerts','model_feedback','recommendations'] LOOP BEGIN EXECUTE format('CREATE POLICY %I ON %I USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id))',t||'_workspace',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['financial_forecasts','performance_scorecards','portfolio_snapshots','renewal_assessments','model_registrations','evaluation_records','model_feedback','recommendations'] LOOP BEGIN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation()',t||'_append_only',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
